  wire PCLK_in;
  wire PENABLE_in;
  wire PLL_MONCLK_in;
  wire PLL_REFCLK_IN_in;
  wire PRESET_N_in;
  wire PSEL_in;
  wire PWRITE_in;
  wire SCAN_CLK_N_IN_EXT_in;
  wire SCAN_CNTRL_CHNL_IN_EXT_in;
  wire SCAN_EDT_UPDT_N_IN_EXT_in;
  wire SCAN_EN_N_IN_EXT_in;
  wire SCAN_MODE_RST_N_IN_EXT_in;
  wire SYSREF_IN1_L_P_in;
  wire SYSREF_IN2_L_P_in;
  wire SYSREF_IN_R_P_in;
  wire SYSREF_N_in;
  wire SYSREF_P_in;
  wire VIN0_N_in;
  wire VIN0_P_in;
  wire VIN1_N_in;
  wire VIN1_P_in;
  wire VIN2_N_in;
  wire VIN2_P_in;
  wire VIN3_N_in;
  wire VIN3_P_in;
  wire VINS_N_in;
  wire VINS_P_in;
  wire [14:0] SCAN_CHNL_IN_EXT_in;
  wire [15:0] CONTROL_COMMON_in;
  wire [15:0] PADDR_in;
  wire [22:0] CONTROL_ADC0_in;
  wire [22:0] CONTROL_ADC1_in;
  wire [22:0] CONTROL_ADC2_in;
  wire [22:0] CONTROL_ADC3_in;
  wire [31:0] PWDATA_in;
  wire [3:0] FABRIC_CLK_IO_in;
  wire [3:0] FABRIC_CLK_OBS_IO_in;
  wire [40:0] DLC_COEFF_in;

`ifdef XIL_TIMING
  wire DLC_CLK_delay;
  wire FABRIC_CLK_delay;
  wire PCLK_delay;
  wire PENABLE_delay;
  wire PSEL_delay;
  wire PWRITE_delay;
  wire [15:0] CONTROL_COMMON_delay;
  wire [15:0] PADDR_delay;
  wire [22:0] CONTROL_ADC0_delay;
  wire [22:0] CONTROL_ADC1_delay;
  wire [22:0] CONTROL_ADC2_delay;
  wire [22:0] CONTROL_ADC3_delay;
  wire [31:0] PWDATA_delay;
  wire [40:0] DLC_COEFF_delay;
`endif

  
  assign CLK_ADC = CLK_ADC_out;
  assign CLK_ADC_SPARE = CLK_ADC_SPARE_out;
  assign CLK_DISTR_OUT_LEFT_P = CLK_DISTR_OUT_LEFT_P_out;
  assign CLK_DISTR_OUT_RIGHT_P = CLK_DISTR_OUT_RIGHT_P_out;
  assign CLK_DISTR_OUT_RIGHT_PLL_P = CLK_DISTR_OUT_RIGHT_PLL_P_out;
  assign CLK_DISTR_OUT_RIGHT_T1_P = CLK_DISTR_OUT_RIGHT_T1_P_out;
  assign DATA_ADC0 = DATA_ADC0_out;
  assign DATA_ADC1 = DATA_ADC1_out;
  assign DATA_ADC2 = DATA_ADC2_out;
  assign DATA_ADC3 = DATA_ADC3_out;
  assign DLC_DATA = DLC_DATA_out;
  assign DLC_VALID = DLC_VALID_out;
  assign PLL_DMON_OUT = PLL_DMON_OUT_out;
  assign PLL_DMON_OUT_SPARE = PLL_DMON_OUT_SPARE_out;
  assign PRDATA = PRDATA_out;
  assign PREADY = PREADY_out;
  assign PSLVERR = PSLVERR_out;
  assign STATUS_ADC0 = STATUS_ADC0_out;
  assign STATUS_ADC1 = STATUS_ADC1_out;
  assign STATUS_ADC2 = STATUS_ADC2_out;
  assign STATUS_ADC3 = STATUS_ADC3_out;
  assign STATUS_COMMON = STATUS_COMMON_out;
  assign SYSREF_OUT1_R_P = SYSREF_OUT1_R_P_out;
  assign SYSREF_OUT2_R_P = SYSREF_OUT2_R_P_out;
  assign SYSREF_OUT_L_P = SYSREF_OUT_L_P_out;

`ifdef XIL_TIMING
  assign CONTROL_ADC0_in = CONTROL_ADC0_delay;
  assign CONTROL_ADC1_in = CONTROL_ADC1_delay;
  assign CONTROL_ADC2_in = CONTROL_ADC2_delay;
  assign CONTROL_ADC3_in = CONTROL_ADC3_delay;
  assign CONTROL_COMMON_in = CONTROL_COMMON_delay;
  assign DLC_CLK_in = DLC_CLK_delay;
  assign DLC_COEFF_in = DLC_COEFF_delay;
  assign FABRIC_CLK_in = FABRIC_CLK_delay;
  assign PADDR_in = PADDR_delay;
  assign PCLK_in = PCLK_delay;
  assign PENABLE_in = PENABLE_delay;
  assign PSEL_in = PSEL_delay;
  assign PWDATA_in = PWDATA_delay;
  assign PWRITE_in = PWRITE_delay;
`else
  assign CONTROL_ADC0_in = CONTROL_ADC0;
  assign CONTROL_ADC1_in = CONTROL_ADC1;
  assign CONTROL_ADC2_in = CONTROL_ADC2;
  assign CONTROL_ADC3_in = CONTROL_ADC3;
  assign CONTROL_COMMON_in = CONTROL_COMMON;
