  assign PCLK_in = PCLK;
  assign PENABLE_in = PENABLE;
  assign PSEL_in = PSEL;
  assign PWDATA_in = PWDATA;
  assign PWRITE_in = PWRITE;
`endif

  assign ADC_CLK_N_in = ADC_CLK_N;
  assign ADC_CLK_P_in = ADC_CLK_P;
  assign CLK_DISTR_IN_LEFT_PLL_P_in = CLK_DISTR_IN_LEFT_PLL_P;
  assign CLK_DISTR_IN_LEFT_P_in = CLK_DISTR_IN_LEFT_P;
  assign CLK_DISTR_IN_LEFT_T1_P_in = CLK_DISTR_IN_LEFT_T1_P;
  assign CLK_DISTR_IN_RIGHT_P_in = CLK_DISTR_IN_RIGHT_P;
  assign CSSD_TRIG_N_in = CSSD_TRIG_N;
  assign FABRIC_CLK_IO_in = FABRIC_CLK_IO;
  assign FABRIC_CLK_OBS_IO_in = FABRIC_CLK_OBS_IO;
  assign FABRIC_CLK_OBS_in = FABRIC_CLK_OBS;
