    .PSLVERR (PSLVERR_out),
    .SCAN_CHNL_OUT_EXT (SCAN_CHNL_OUT_EXT_out),
    .SCAN_CNTRL_CHNL_OUT_EXT (SCAN_CNTRL_CHNL_OUT_EXT_out),
    .STATUS_ADC0 (STATUS_ADC0_out),
    .STATUS_ADC1 (STATUS_ADC1_out),
    .STATUS_ADC2 (STATUS_ADC2_out),
    .STATUS_ADC3 (STATUS_ADC3_out),
    .STATUS_COMMON (STATUS_COMMON_out),
    .SYSREF_OUT1_R_P (SYSREF_OUT1_R_P_out),
    .SYSREF_OUT2_R_P (SYSREF_OUT2_R_P_out),
    .SYSREF_OUT_L_P (SYSREF_OUT_L_P_out),
    .TEST_STATUS (TEST_STATUS_out),
    .ADC_CLK_N (ADC_CLK_N_in),
    .ADC_CLK_P (ADC_CLK_P_in),
    .CLK_DISTR_IN_LEFT_P (CLK_DISTR_IN_LEFT_P_in),
